"""Visual test drive for M4 operating Empty Chair."""
from fastapi import Request
from fastapi.responses import HTMLResponse

import app as core


@core.app.get("/m4-operator", response_class=HTMLResponse)
def m4_operator_demo(request: Request):
    user, redirect = core.login_required_redirect(request)
    if redirect:
        return redirect

    html = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>M4 Operator // Empty Chair</title>
<style>
:root{--bg:#080908;--ink:#f0eadf;--muted:#9e9b91;--line:#292c27;--panel:#0e100e;--signal:#d8ff45;--green:#9bd76a;--danger:#ff6b5f}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% 18%,rgba(216,255,69,.055),transparent 31%),var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,sans-serif;min-height:100vh}.shell{max-width:1120px;margin:auto;padding:28px 22px 70px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-bottom:22px;border-bottom:1px solid var(--line)}.brand{display:flex;gap:13px;align-items:center}.mark{width:64px;height:32px;position:relative}.mark:before,.mark:after{content:'';position:absolute;top:14px;height:4px;background:var(--ink);width:27px}.mark:before{left:0}.mark:after{right:0}.mark i{position:absolute;left:29px;top:12px;width:8px;height:8px;border-radius:50%;background:var(--signal);box-shadow:0 0 20px var(--signal)}.brand b{font-size:14px;letter-spacing:.18em}.brand small{display:block;color:#70756b;margin-top:3px;font:500 8px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.08em;text-transform:uppercase}.back{color:#b8b9b2;font-size:12px;text-decoration:none;border:1px solid #3d413a;padding:9px 12px}.hero{padding:72px 0 42px;display:grid;grid-template-columns:1.15fr .85fr;gap:60px;align-items:end}.eyebrow{color:var(--signal);font:700 10px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.16em;text-transform:uppercase}.hero h1{font-size:clamp(48px,7vw,84px);line-height:.92;letter-spacing:-.055em;margin:16px 0 20px}.hero h1 em{font-style:normal;color:#8b8f86}.hero p{max-width:690px;color:#b1b3ab;font-size:17px;line-height:1.7}.state{border:1px solid #343830;background:linear-gradient(145deg,#10130f,#090a09);padding:24px;box-shadow:0 30px 80px #000}.state .pulse{width:11px;height:11px;border-radius:50%;background:var(--signal);box-shadow:0 0 26px rgba(216,255,69,.9);margin-bottom:18px}.state strong{font-size:30px;display:block}.state span{display:block;color:#72776e;margin-top:8px;font:600 10px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.12em;text-transform:uppercase}.workspace{display:grid;grid-template-columns:.9fr 1.1fr;gap:1px;background:var(--line);border:1px solid var(--line)}.panel{background:#0b0d0b;padding:28px;min-height:470px}.panel h2{font-size:24px;margin:8px 0 6px}.panel>p{color:#858980;font-size:13px;line-height:1.55;margin-bottom:24px}.opening-list{display:grid;gap:9px}.opening{width:100%;text-align:left;background:#0e110e;border:1px solid #30342d;color:var(--ink);padding:15px;cursor:pointer;transition:.15s}.opening:hover,.opening.selected{border-color:var(--signal);background:#11150e}.opening b{display:block;font-size:14px}.opening span{display:block;color:#777c72;font:500 10px ui-monospace,SFMono-Regular,Menlo,monospace;margin-top:6px}.empty{border:1px dashed #343830;padding:20px;color:#777b72;line-height:1.6;font-size:13px}.terminal{background:#070907;border:1px solid #343830;min-height:294px;padding:20px;font:500 12px/1.75 ui-monospace,SFMono-Regular,Menlo,monospace;color:#ced2c8;white-space:pre-wrap}.terminal .hot{color:var(--signal)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.button{appearance:none;border:1px solid var(--signal);background:var(--signal);color:#090a09;padding:13px 18px;font-size:11px;font-weight:900;letter-spacing:.09em;text-transform:uppercase;cursor:pointer}.button.secondary{background:transparent;color:var(--ink);border-color:#4a4f45}.button:disabled{opacity:.35;cursor:not-allowed}.guardrails{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.guardrails span{border:1px solid #30352d;color:#858b80;padding:6px 8px;font:600 8px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.08em;text-transform:uppercase}.candidate{display:grid;grid-template-columns:1fr auto;gap:4px 16px;padding:11px 0;border-top:1px solid #242821}.candidate b{font-size:12px}.candidate small{color:#777c72;font-size:9px}.candidate strong{grid-column:2;grid-row:1/3;align-self:center;color:var(--signal);font:700 15px ui-monospace,SFMono-Regular,Menlo,monospace}.note{margin-top:26px;padding:15px 17px;border-left:2px solid #5d6258;background:#0f110f;color:#888d83;font-size:12px;line-height:1.6}.success{border-left-color:var(--signal);color:#cbd2c4}.error{border-left-color:var(--danger);color:#e0b4af}@media(max-width:800px){.hero,.workspace{grid-template-columns:1fr}.hero{gap:28px;padding-top:48px}.panel{min-height:auto}.top{align-items:flex-start}}
</style>
</head>
<body><div class="shell">
<div class="top"><div class="brand"><div class="mark"><i></i></div><div><b>EMPTY CHAIR</b><small>M4 operating intelligence</small></div></div><a class="back" href="/dashboard">Back to app</a></div>
<section class="hero"><div><div class="eyebrow">Observe → predict → act → measure → learn</div><h1>M4 doesn't just advise.<br><em>She operates.</em></h1><p>Select a real open slot from this shop. M4 will inspect the opportunity, rank consented customers, show you her reasoning signals, then—only when you tell her to—hand the opening to Empty Chair's existing guarded recovery engine.</p></div><aside class="state"><div class="pulse"></div><strong id="stateTitle">Observing</strong><span id="stateSub">Reading current shop state</span></aside></section>
<section class="workspace"><div class="panel"><div class="eyebrow">01 // Perishable inventory</div><h2>Open chairs</h2><p>Only openings currently marked OPEN for this signed-in shop appear here.</p><div id="openings" class="opening-list"><div class="empty">Loading live openings…</div></div></div>
<div class="panel"><div class="eyebrow">02 // M4 decision</div><h2>Reason before action</h2><p>Preview is read-only. Activate uses the production recovery path and all existing safeguards.</p><div id="terminal" class="terminal">M4 // WAITING

Select an opening to inspect.</div><div class="actions"><button id="preview" class="button secondary" disabled>Preview M4 decision</button><button id="activate" class="button" disabled>Activate recovery</button></div><div id="guards" class="guardrails"></div><div id="message"></div></div></section>
</div>
<script>
(()=>{let selected=null,previewed=false;const openings=document.getElementById('openings'),terminal=document.getElementById('terminal'),preview=document.getElementById('preview'),activate=document.getElementById('activate'),guards=document.getElementById('guards'),message=document.getElementById('message'),stateTitle=document.getElementById('stateTitle'),stateSub=document.getElementById('stateSub');
function state(a,b){stateTitle.textContent=a;stateSub.textContent=b}
function fmt(o){return `${o.date||'Date TBD'} · ${o.start_time||''}${o.end_time?'–'+o.end_time:''} · $${Number(o.price||0).toLocaleString()}`}
async function load(){try{const r=await fetch('/api/m4/operator/status',{cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Could not read openings');if(!j.openings.length){openings.innerHTML='<div class="empty">No OPEN slots are currently available. Create an opening or start Fill Chairs, then return here.</div>';state('Ready','No open inventory found');return}openings.innerHTML='';j.openings.forEach(o=>{const b=document.createElement('button');b.className='opening';b.innerHTML=`<b>${fmt(o)}</b><span>${o.id} · artist ${o.artist_id}</span>`;b.onclick=()=>{document.querySelectorAll('.opening').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selected=o;previewed=false;preview.disabled=false;activate.disabled=true;guards.innerHTML='';message.innerHTML='';terminal.textContent=`M4 // OBSERVATION\n\nOPENING ${o.id}\n${fmt(o)}\nARTIST ${o.artist_id}\n\nReady to inspect consented demand.`;state('Observing','Opening selected')};openings.appendChild(b)});state('Ready',`${j.openings.length} open slot${j.openings.length===1?'':'s'} observed`)}catch(e){openings.innerHTML=`<div class="empty">${e.message}</div>`;state('Interrupted','Could not read shop state')}}
preview.onclick=async()=>{if(!selected)return;preview.disabled=true;activate.disabled=true;message.innerHTML='';state('Predicting','Ranking consented customers');terminal.textContent='M4 // THINKING\n\nReading behavior, fit, modeled uplift and confidence…';try{const f=new FormData();f.append('opening_id',selected.id);const r=await fetch('/api/m4/operator/preview',{method:'POST',body:f,cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Preview failed');const lines=j.m4_top_candidates.map((c,i)=>`${String(i+1).padStart(2,'0')}  ${c.customer_id}\n    booking ${Math.round(c.booking_probability*100)}% · uplift ${Math.round(c.incremental_uplift*100)}% · confidence ${Math.round(c.confidence*100)}%${c.expected_value==null?'':` · EV $${c.expected_value}`}`).join('\n\n');terminal.textContent=`M4 // DECISION PREVIEW\n\n${j.consented_candidates} consented customers observed\n${j.m4_top_candidates.length} strongest candidates shown\n\n${lines||'No eligible modeled candidates returned.'}\n\nEXECUTION: PREVIEW ONLY`;guards.innerHTML=(j.guardrails||[]).map(x=>`<span>${x}</span>`).join('');previewed=true;activate.disabled=false;state('Ready to act','Preview complete');}catch(e){message.innerHTML=`<div class="note error">${e.message}</div>`;state('Interrupted','Preview failed')}finally{preview.disabled=false}}
activate.onclick=async()=>{if(!selected||!previewed)return;if(!confirm('Activate Empty Chair recovery for this opening? This uses the real guarded recovery engine.'))return;activate.disabled=true;preview.disabled=true;state('Acting','Handing opening to Empty Chair');terminal.textContent+='\n\nM4 // ACTION\nHanding opening to guarded recovery engine…';try{const f=new FormData();f.append('opening_id',selected.id);const r=await fetch('/api/m4/operator/activate',{method:'POST',body:f,cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||j.message||'Activation failed');terminal.textContent+=`\n\nOFFER ${j.offer_id||'none'}\nSTATUS ${j.ok?'ACTIVATED':'BLOCKED'}`;message.innerHTML=`<div class="note success"><b>M4 acted.</b><br>${j.message}</div>`;state(j.ok?'Operating':'Protected',j.ok?'Recovery engine active':'Safety or eligibility rule stopped activation');setTimeout(load,1200)}catch(e){message.innerHTML=`<div class="note error">${e.message}</div>`;state('Protected','Activation did not proceed')}finally{preview.disabled=false}}
load();})();
</script></body></html>'''
    return HTMLResponse(html, headers={"Cache-Control": "no-store"})
